void ekf_update_vel_body(const float Z[N_MEASUREMENTS_VEL_BODY], int num_iter) {
    // parameters
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_VEL_BODY];
    static float H[N_MEASUREMENTS_VEL_BODY*N_STATES];
    static float HP[N_MEASUREMENTS_VEL_BODY*N_STATES];
    static float S[N_MEASUREMENTS_VEL_BODY*N_MEASUREMENTS_VEL_BODY];
    static float S_chol[N_MEASUREMENTS_VEL_BODY*N_MEASUREMENTS_VEL_BODY];
    static float S_iDiag[N_MEASUREMENTS_VEL_BODY];
    static float K[N_STATES*N_MEASUREMENTS_VEL_BODY];

    // renaming
    float *R = ekf_R_vel_body;

    // iterated ekf
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_vel_body(H);

        // compute h
        ekf_h_vel_body(h);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_VEL_BODY; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_VEL_BODY] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_VEL_BODY] += H[i+k*N_MEASUREMENTS_VEL_BODY] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_VEL_BODY; i++) {
            for (int j = 0; j < N_MEASUREMENTS_VEL_BODY; j++) {
                S[i+j*N_MEASUREMENTS_VEL_BODY] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_VEL_BODY] += H[i+k*N_MEASUREMENTS_VEL_BODY] * HP[j+k*N_MEASUREMENTS_VEL_BODY];
                }
            }
            S[i+i*N_MEASUREMENTS_VEL_BODY] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_VEL_BODY);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_VEL_BODY];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_VEL_BODY, (HP+(i*N_MEASUREMENTS_VEL_BODY)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_VEL_BODY; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // UPDATE STEP X_new = ...
        for (int i = 0; i < N_STATES; i++) {
            X_new[i] = X[i];
            for (int j = 0; j < N_MEASUREMENTS_VEL_BODY; j++) {
                X_new[i] += K[i + j*N_STATES] * (Z[j] - h[j]);
            }
        }   

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // UPDATE STEP P_new = (I - K*H)*P
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) { // only lower diagonal
            P_new[i*(i+1)/2 + j] = P[i*(i+1)/2 + j];
            for (int k = 0; k < N_MEASUREMENTS_VEL_BODY; k++) {
                P_new[i*(i+1)/2 + j] -= K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_VEL_BODY];
            }
        }
    }

    // swap P, P_new pointers
    swap_ptr = P;
    P = P_new;
    P_new = swap_ptr;
}
// points_1 measurement model:
float ekf_R_points_1[N_MEASUREMENTS_POINTS_1];   // Kalman filter measurement noise covariance matrix (diagonal)

void ekf_set_R_points_1(float R_diag[N_MEASUREMENTS_POINTS_1]) {
    for (int i=0; i<N_MEASUREMENTS_POINTS_1; i++) {
        ekf_R_points_1[i] = R_diag[i];
    }
}

void ekf_h_points_1(float h[N_MEASUREMENTS_POINTS_1], const float param[7]) {
    // parameters
    float fx = param[0];
    float fy = param[1];
    float cx = param[2];
    float cy = param[3];
    float p3d0_x = param[4];
    float p3d0_y = param[5];
    float p3d0_z = param[6];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[0] + p3d0_x;
    tmp[2] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[3] = X[7]*tmp[2];
    tmp[4] = -X[1] + p3d0_y;
    tmp[5] = X[8]*tmp[2];
    tmp[6] = -X[2] + p3d0_z;
    tmp[7] = X[9]*tmp[2];
    tmp[8] = tmp[1]*tmp[3] + tmp[4]*tmp[5] + tmp[6]*tmp[7];
    tmp[9] = X[6]*tmp[2];
    tmp[10] = tmp[2]*tmp[4];
    tmp[11] = -X[7]*tmp[10] + tmp[1]*tmp[5] + tmp[6]*tmp[9];
    tmp[12] = X[9]*tmp[10] + tmp[1]*tmp[9] - tmp[5]*tmp[6];
    tmp[13] = -tmp[1]*tmp[7] + tmp[3]*tmp[6] + tmp[4]*tmp[9];
    tmp[14] = -X[18] + tmp[11]*tmp[9] + tmp[12]*tmp[5] - tmp[13]*tmp[3] + tmp[7]*tmp[8];
    tmp[15] = cosf(X[20]);
    tmp[16] = cosf(X[21]);
    tmp[17] = -X[16] - tmp[11]*tmp[5] + tmp[12]*tmp[9] + tmp[13]*tmp[7] + tmp[3]*tmp[8];
    tmp[18] = sinf(X[21]);
    tmp[19] = -X[17] + tmp[11]*tmp[3] - tmp[12]*tmp[7] + tmp[13]*tmp[9] + tmp[5]*tmp[8];
    tmp[20] = 1.0/(-tmp[0]*tmp[14] + tmp[15]*tmp[16]*tmp[17] + tmp[15]*tmp[18]*tmp[19]);
    tmp[21] = sinf(X[19]);
    tmp[22] = tmp[14]*tmp[15];
    tmp[23] = cosf(X[19]);
    tmp[24] = tmp[16]*tmp[23];
    tmp[25] = tmp[18]*tmp[21];
    tmp[26] = tmp[16]*tmp[21];
    h[0] = cx + fx*tmp[20]*(tmp[17]*(tmp[0]*tmp[26] - tmp[18]*tmp[23]) + tmp[19]*(tmp[0]*tmp[25] + tmp[24]) + tmp[21]*tmp[22]);
    h[1] = cy + fy*tmp[20]*(tmp[17]*(tmp[0]*tmp[24] + tmp[25]) + tmp[19]*(tmp[0]*tmp[18]*tmp[23] - tmp[26]) + tmp[22]*tmp[23]);
}

