void ekf_update_points_1(const float Z[N_MEASUREMENTS_POINTS_1], const float param[7], int num_iter) {
    // parameters
    float fx = param[0];
    float fy = param[1];
    float cx = param[2];
    float cy = param[3];
    float p3d0_x = param[4];
    float p3d0_y = param[5];
    float p3d0_z = param[6];
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POINTS_1];
    static float H[N_MEASUREMENTS_POINTS_1*N_STATES];
    static float HP[N_MEASUREMENTS_POINTS_1*N_STATES];
    static float S[N_MEASUREMENTS_POINTS_1*N_MEASUREMENTS_POINTS_1];
    static float S_chol[N_MEASUREMENTS_POINTS_1*N_MEASUREMENTS_POINTS_1];
    static float S_iDiag[N_MEASUREMENTS_POINTS_1];
    static float K[N_STATES*N_MEASUREMENTS_POINTS_1];

    // renaming
    float *R = ekf_R_points_1;

    // iterated ekf
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_points_1(H, param);

        // compute h
        ekf_h_points_1(h, param);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POINTS_1; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POINTS_1] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POINTS_1] += H[i+k*N_MEASUREMENTS_POINTS_1] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POINTS_1; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POINTS_1; j++) {
                S[i+j*N_MEASUREMENTS_POINTS_1] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POINTS_1] += H[i+k*N_MEASUREMENTS_POINTS_1] * HP[j+k*N_MEASUREMENTS_POINTS_1];
                }
            }
            S[i+i*N_MEASUREMENTS_POINTS_1] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_1);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POINTS_1];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_1, (HP+(i*N_MEASUREMENTS_POINTS_1)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POINTS_1; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // UPDATE STEP X_new = ...
        for (int i = 0; i < N_STATES; i++) {
            X_new[i] = X[i];
            for (int j = 0; j < N_MEASUREMENTS_POINTS_1; j++) {
                X_new[i] += K[i + j*N_STATES] * (Z[j] - h[j]);
            }
        }   

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // UPDATE STEP P_new = (I - K*H)*P
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) { // only lower diagonal
            P_new[i*(i+1)/2 + j] = P[i*(i+1)/2 + j];
            for (int k = 0; k < N_MEASUREMENTS_POINTS_1; k++) {
                P_new[i*(i+1)/2 + j] -= K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POINTS_1];
            }
        }
    }

    // swap P, P_new pointers
    swap_ptr = P;
    P = P_new;
    P_new = swap_ptr;
}
// points_2 measurement model:
float ekf_R_points_2[N_MEASUREMENTS_POINTS_2];   // Kalman filter measurement noise covariance matrix (diagonal)

void ekf_set_R_points_2(float R_diag[N_MEASUREMENTS_POINTS_2]) {
    for (int i=0; i<N_MEASUREMENTS_POINTS_2; i++) {
        ekf_R_points_2[i] = R_diag[i];
    }
}

void ekf_h_points_2(float h[N_MEASUREMENTS_POINTS_2], const float param[10]) {
    // parameters
    float fx = param[0];
    float fy = param[1];
    float cx = param[2];
    float cy = param[3];
    float p3d0_x = param[4];
    float p3d0_y = param[5];
    float p3d0_z = param[6];
    float p3d1_x = param[7];
    float p3d1_y = param[8];
    float p3d1_z = param[9];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[18];
    tmp[2] = -X[0] + p3d0_x;
    tmp[3] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[4] = X[7]*tmp[3];
    tmp[5] = -X[1] + p3d0_y;
    tmp[6] = X[8]*tmp[3];
    tmp[7] = -X[2] + p3d0_z;
    tmp[8] = X[9]*tmp[3];
    tmp[9] = tmp[2]*tmp[4] + tmp[5]*tmp[6] + tmp[7]*tmp[8];
    tmp[10] = X[6]*tmp[3];
    tmp[11] = tmp[3]*tmp[5];
    tmp[12] = -X[7]*tmp[11] + tmp[10]*tmp[7] + tmp[2]*tmp[6];
    tmp[13] = X[9]*tmp[11] + tmp[10]*tmp[2] - tmp[6]*tmp[7];
    tmp[14] = tmp[10]*tmp[5] - tmp[2]*tmp[8] + tmp[4]*tmp[7];
    tmp[15] = tmp[10]*tmp[12] + tmp[13]*tmp[6] - tmp[14]*tmp[4] + tmp[1] + tmp[8]*tmp[9];
    tmp[16] = -X[16];
    tmp[17] = tmp[10]*tmp[13] - tmp[12]*tmp[6] + tmp[14]*tmp[8] + tmp[16] + tmp[4]*tmp[9];
    tmp[18] = cosf(X[21]);
    tmp[19] = cosf(X[20]);
    tmp[20] = tmp[18]*tmp[19];
    tmp[21] = -X[17];
    tmp[22] = tmp[10]*tmp[14] + tmp[12]*tmp[4] - tmp[13]*tmp[8] + tmp[21] + tmp[6]*tmp[9];
    tmp[23] = sinf(X[21]);
    tmp[24] = tmp[19]*tmp[23];
    tmp[25] = 1.0/(-tmp[0]*tmp[15] + tmp[17]*tmp[20] + tmp[22]*tmp[24]);
    tmp[26] = sinf(X[19]);
    tmp[27] = tmp[15]*tmp[19];
    tmp[28] = cosf(X[19]);
    tmp[29] = tmp[18]*tmp[28];
    tmp[30] = tmp[23]*tmp[26];
    tmp[31] = tmp[0]*tmp[30] + tmp[29];
    tmp[32] = tmp[18]*tmp[26];
    tmp[33] = tmp[0]*tmp[32] - tmp[23]*tmp[28];
    tmp[34] = tmp[0]*tmp[29] + tmp[30];
    tmp[35] = tmp[0]*tmp[23]*tmp[28] - tmp[32];
    tmp[36] = -X[0] + p3d1_x;
    tmp[37] = -X[1] + p3d1_y;
    tmp[38] = -X[2] + p3d1_z;
    tmp[39] = tmp[36]*tmp[4] + tmp[37]*tmp[6] + tmp[38]*tmp[8];
    tmp[40] = tmp[10]*tmp[38] + tmp[36]*tmp[6] - tmp[37]*tmp[4];
    tmp[41] = tmp[10]*tmp[36] + tmp[37]*tmp[8] - tmp[38]*tmp[6];
    tmp[42] = tmp[10]*tmp[37] - tmp[36]*tmp[8] + tmp[38]*tmp[4];
    tmp[43] = tmp[10]*tmp[40] + tmp[1] + tmp[39]*tmp[8] + tmp[41]*tmp[6] - tmp[42]*tmp[4];
    tmp[44] = tmp[10]*tmp[41] + tmp[16] + tmp[39]*tmp[4] - tmp[40]*tmp[6] + tmp[42]*tmp[8];
    tmp[45] = tmp[10]*tmp[42] + tmp[21] + tmp[39]*tmp[6] + tmp[40]*tmp[4] - tmp[41]*tmp[8];
    tmp[46] = 1.0/(-tmp[0]*tmp[43] + tmp[20]*tmp[44] + tmp[24]*tmp[45]);
    tmp[47] = tmp[19]*tmp[43];
    h[0] = cx + fx*tmp[25]*(tmp[17]*tmp[33] + tmp[22]*tmp[31] + tmp[26]*tmp[27]);
    h[1] = cy + fy*tmp[25]*(tmp[17]*tmp[34] + tmp[22]*tmp[35] + tmp[27]*tmp[28]);
    h[2] = cx + fx*tmp[46]*(tmp[26]*tmp[47] + tmp[31]*tmp[45] + tmp[33]*tmp[44]);
    h[3] = cy + fy*tmp[46]*(tmp[28]*tmp[47] + tmp[34]*tmp[44] + tmp[35]*tmp[45]);
}

