void ekf_update_points_2(const float Z[N_MEASUREMENTS_POINTS_2], const float param[10], int num_iter) {
    // parameters
    float fx = param[0];
    float fy = param[1];
    float cx = param[2];
    float cy = param[3];
    float p3d0_x = param[4];
    float p3d0_y = param[5];
    float p3d0_z = param[6];
    float p3d1_x = param[7];
    float p3d1_y = param[8];
    float p3d1_z = param[9];
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POINTS_2];
    static float H[N_MEASUREMENTS_POINTS_2*N_STATES];
    static float HP[N_MEASUREMENTS_POINTS_2*N_STATES];
    static float S[N_MEASUREMENTS_POINTS_2*N_MEASUREMENTS_POINTS_2];
    static float S_chol[N_MEASUREMENTS_POINTS_2*N_MEASUREMENTS_POINTS_2];
    static float S_iDiag[N_MEASUREMENTS_POINTS_2];
    static float K[N_STATES*N_MEASUREMENTS_POINTS_2];

    // renaming
    float *R = ekf_R_points_2;

    // iterated ekf
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_points_2(H, param);

        // compute h
        ekf_h_points_2(h, param);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POINTS_2; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POINTS_2] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POINTS_2] += H[i+k*N_MEASUREMENTS_POINTS_2] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POINTS_2; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POINTS_2; j++) {
                S[i+j*N_MEASUREMENTS_POINTS_2] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POINTS_2] += H[i+k*N_MEASUREMENTS_POINTS_2] * HP[j+k*N_MEASUREMENTS_POINTS_2];
                }
            }
            S[i+i*N_MEASUREMENTS_POINTS_2] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_2);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POINTS_2];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_2, (HP+(i*N_MEASUREMENTS_POINTS_2)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POINTS_2; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // UPDATE STEP X_new = ...
        for (int i = 0; i < N_STATES; i++) {
            X_new[i] = X[i];
            for (int j = 0; j < N_MEASUREMENTS_POINTS_2; j++) {
                X_new[i] += K[i + j*N_STATES] * (Z[j] - h[j]);
            }
        }   

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // UPDATE STEP P_new = (I - K*H)*P
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) { // only lower diagonal
            P_new[i*(i+1)/2 + j] = P[i*(i+1)/2 + j];
            for (int k = 0; k < N_MEASUREMENTS_POINTS_2; k++) {
                P_new[i*(i+1)/2 + j] -= K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POINTS_2];
            }
        }
    }

    // swap P, P_new pointers
    swap_ptr = P;
    P = P_new;
    P_new = swap_ptr;
}
