    float p3d3_y = param[14];
    float p3d3_z = param[15];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[18];
    tmp[2] = -X[0] + p3d0_x;
    tmp[3] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[4] = X[7]*tmp[3];
