    tmp[14] = tmp[10]*tmp[5] - tmp[2]*tmp[8] + tmp[4]*tmp[7];
    tmp[15] = tmp[10]*tmp[12] + tmp[13]*tmp[6] - tmp[14]*tmp[4] + tmp[1] + tmp[8]*tmp[9];
    tmp[16] = -X[16];
    tmp[17] = tmp[10]*tmp[13] - tmp[12]*tmp[6] + tmp[14]*tmp[8] + tmp[16] + tmp[4]*tmp[9];
    tmp[18] = cosf(X[21]);
    tmp[19] = cosf(X[20]);
