    tmp[49] = -X[1] + p3d2_y;
    tmp[50] = -X[2] + p3d2_z;
    tmp[51] = tmp[48]*tmp[4] + tmp[49]*tmp[6] + tmp[50]*tmp[8];
    tmp[52] = tmp[10]*tmp[50] + tmp[48]*tmp[6] - tmp[49]*tmp[4];
    tmp[53] = tmp[10]*tmp[48] + tmp[49]*tmp[8] - tmp[50]*tmp[6];
    tmp[54] = tmp[10]*tmp[49] - tmp[48]*tmp[8] + tmp[4]*tmp[50];
    tmp[55] = tmp[10]*tmp[52] + tmp[1] - tmp[4]*tmp[54] + tmp[51]*tmp[8] + tmp[53]*tmp[6];
    tmp[56] = tmp[10]*tmp[53] + tmp[16] + tmp[4]*tmp[51] - tmp[52]*tmp[6] + tmp[54]*tmp[8];
    tmp[57] = tmp[10]*tmp[54] + tmp[21] + tmp[4]*tmp[52] + tmp[51]*tmp[6] - tmp[53]*tmp[8];
    tmp[58] = 1.0/(-tmp[0]*tmp[55] + tmp[20]*tmp[56] + tmp[24]*tmp[57]);
