    tmp[69] = tmp[10]*tmp[66] + tmp[21] + tmp[4]*tmp[64] + tmp[63]*tmp[6] - tmp[65]*tmp[8];
    tmp[70] = 1.0/(-tmp[0]*tmp[67] + tmp[20]*tmp[68] + tmp[24]*tmp[69]);
    tmp[71] = tmp[19]*tmp[67];
    h[0] = cx + fx*tmp[25]*(tmp[17]*tmp[33] + tmp[22]*tmp[31] + tmp[26]*tmp[27]);
    h[1] = cy + fy*tmp[25]*(tmp[17]*tmp[34] + tmp[22]*tmp[35] + tmp[27]*tmp[28]);
