void ekf_update_points_11(const float Z[N_MEASUREMENTS_POINTS_11], const float param[37], int num_iter) {
    // parameters
    float fx = param[0];
    float fy = param[1];
    float cx = param[2];
    float cy = param[3];
    float p3d0_x = param[4];
    float p3d0_y = param[5];
    float p3d0_z = param[6];
    float p3d1_x = param[7];
    float p3d1_y = param[8];
    float p3d1_z = param[9];
    float p3d2_x = param[10];
    float p3d2_y = param[11];
    float p3d2_z = param[12];
    float p3d3_x = param[13];
    float p3d3_y = param[14];
    float p3d3_z = param[15];
    float p3d4_x = param[16];
    float p3d4_y = param[17];
    float p3d4_z = param[18];
    float p3d5_x = param[19];
    float p3d5_y = param[20];
    float p3d5_z = param[21];
    float p3d6_x = param[22];
    float p3d6_y = param[23];
    float p3d6_z = param[24];
    float p3d7_x = param[25];
    float p3d7_y = param[26];
    float p3d7_z = param[27];
    float p3d8_x = param[28];
    float p3d8_y = param[29];
    float p3d8_z = param[30];
    float p3d9_x = param[31];
    float p3d9_y = param[32];
    float p3d9_z = param[33];
    float p3d10_x = param[34];
    float p3d10_y = param[35];
    float p3d10_z = param[36];
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POINTS_11];
    static float H[N_MEASUREMENTS_POINTS_11*N_STATES];
    static float HP[N_MEASUREMENTS_POINTS_11*N_STATES];
    static float S[N_MEASUREMENTS_POINTS_11*N_MEASUREMENTS_POINTS_11];
    static float S_chol[N_MEASUREMENTS_POINTS_11*N_MEASUREMENTS_POINTS_11];
    static float S_iDiag[N_MEASUREMENTS_POINTS_11];
    static float K[N_STATES*N_MEASUREMENTS_POINTS_11];

    // renaming
    float *R = ekf_R_points_11;

    // iterated ekf
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_points_11(H, param);

        // compute h
        ekf_h_points_11(h, param);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POINTS_11; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POINTS_11] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POINTS_11] += H[i+k*N_MEASUREMENTS_POINTS_11] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POINTS_11; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POINTS_11; j++) {
                S[i+j*N_MEASUREMENTS_POINTS_11] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POINTS_11] += H[i+k*N_MEASUREMENTS_POINTS_11] * HP[j+k*N_MEASUREMENTS_POINTS_11];
                }
            }
            S[i+i*N_MEASUREMENTS_POINTS_11] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_11);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POINTS_11];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_11, (HP+(i*N_MEASUREMENTS_POINTS_11)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POINTS_11; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // UPDATE STEP X_new = ...
        for (int i = 0; i < N_STATES; i++) {
            X_new[i] = X[i];
            for (int j = 0; j < N_MEASUREMENTS_POINTS_11; j++) {
                X_new[i] += K[i + j*N_STATES] * (Z[j] - h[j]);
            }
        }   

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // UPDATE STEP P_new = (I - K*H)*P
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) { // only lower diagonal
            P_new[i*(i+1)/2 + j] = P[i*(i+1)/2 + j];
            for (int k = 0; k < N_MEASUREMENTS_POINTS_11; k++) {
                P_new[i*(i+1)/2 + j] -= K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POINTS_11];
            }
        }
    }

    // swap P, P_new pointers
    swap_ptr = P;
    P = P_new;
    P_new = swap_ptr;
}
// points_12 measurement model:
float ekf_R_points_12[N_MEASUREMENTS_POINTS_12];   // Kalman filter measurement noise covariance matrix (diagonal)

void ekf_set_R_points_12(float R_diag[N_MEASUREMENTS_POINTS_12]) {
    for (int i=0; i<N_MEASUREMENTS_POINTS_12; i++) {
        ekf_R_points_12[i] = R_diag[i];
    }
}

